  if(d.bCompareFree||d.bPlanFree){if(s.assets.length>=40){api.notify('Quarante achats maximum.');return true;}const key='free-'+Date.now().toString(36)+'-'+s.assets.length;s.assets.push({key,itemId:'',name:d.bPlanFree?'Mon but':'Mon achat libre',price:null,referencePrice:null,extras:0,fees:0,owned:false,incomeMode:'none',boostHourly:0,utility:3});if(d.bPlanFree){s.plan.key=key;s.plan.kind='purchase';}else s.compare.keys.push(key);refresh(d.bPlanFree?'plan-price':'compare-price-'+(s.compare.keys.length-1));return true;}
